     AND (to_regclass('public.mp_task_staffs_sv') IS NULL OR EXISTS (
       SELECT 1
       FROM pg_class c
       JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = 'public' AND c.relname = 'mp_task_staffs_sv' AND c.relkind = 'v'
     )) THEN
    EXECUTE $view$
