-- PATROL_1.0.0_patrolTask_detailList from /Users/zhangchu/Documents/ADP/mes-modules-patrol-intake/modules/patrol/PATROL_6.0.4.0/service/src/main/resources/META-INF/bap/module.xml
INSERT INTO public.runtime_customer_condition (code, ec_env, version, create_time, modify_time, valid, entity_code, module_code, proj_flag, condition_sql, json_condition, dataclassific_code, datagrid_code, view_code)
VALUES ('PATROL_1.0.0_patrolTask_detailList', 'product', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, true, 'PATROL_1.0.0_patrolTask', 'PATROL_1.0.0', false, 'if (customCondition) {
	def condition = "";
	if (customCondition.taskId) {
		condition = "\"taskDetail\".PATROL_TASK = \${taskId, Long} ";
	} else if (customCondition.taskAreaId) {
		condition = "\"taskDetail\".TASK_AREA_ID = \${taskAreaId, Long} ";
	} else {
		condition = "(\"taskDetail\".valid = 1)";
	}
	// 异常
	if(customCondition.type == ''abnormal'') {
		return condition + " AND ( \"taskDetail\".REAL_VALUE = ''PATROL_realValue/abnormal'' OR  \"taskDetail\".REAL_VALUE = ''PATROL_realValue/doubtful'')";
	}
	// 跳检
	if(customCondition.type == ''skip''){
		return condition + " AND ( \"taskDetail\".IS_REAL_PASS = 1)";
	}
	// 漏检
	if(customCondition.type == ''miss''){
		return condition + " AND ( (\"taskDetail\".REAL_VALUE is null OR \"taskDetail\".CONCLUSE is NULL)) AND (\"taskDetail\".IS_REAL_PASS = 0 OR \"taskDetail\".IS_REAL_PASS IS NULL) AND \"taskDetail\".PATROL_TASK in(select ID from MP_POTROL_TASKS where ( TASK_STATE = ''PATROL_taskState/completed''))";
	}
	// 所有巡检项
	if(customCondition.type == ''total''){
		return condition;
	}
}
// 必须要返回一个条件，否则获取到空的自定义条件会报错，如果后续没这个bug了，可以删掉这个条件
return ''(\"taskDetail\".valid = 1)'';', NULL, NULL, NULL, 'PATROL_1.0.0_patrolTask_detailList')
