:false},"colNum":4,"layoutType":"classic","selfAdaption":true,"events":[{"function":"debugger;\nvar emessage=\"\";\n//结束时间类型\nvar finishType=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.finishTimeType\").getValue().value;\n//重复次数\nif(finishType==\"PATROL_finishType/repeatNum\"){\n\tvar times=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.repeatNum\").getValue();\n\tif(times==null){\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576803073190\");\n\t}\n}\n//结束时间\nif(finishType==\"PATROL_finishType/finishTime\"){\n\tvar endTime=ReactAPI.getComponentAPI(\"DatePicker\").APIs(\"patrolPlan.endTime\").getValue();\n\tvar startTime=ReactAPI.getComponentAPI(\"DatePicker\").APIs(\"patrolPlan.startTime\").getValue();\n\tif(endTime==null){\n\t\t// 结束时间：结束时间不允许为空！</br>\"\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576803630267\");\n\t}else{\n\t\tif(!(endTime>startTime)){//结束时间小于开始时间报错\n\t\t\t// \"结束时间：结束时间必须大于开始时间！</br>\"\n\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576803706530\");\n\t\t}\n\t}\n}\n//巡检模式\nvar patrolType=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.potrolType\").getValue().value;\n//按小时重复\nif(patrolType==\"PATROL_planType/hour\"){\n\tvar hourTime=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.hour\").getValue();//1\n\tif(hourTime==null){\n\t\t// \"重复模式：每几小时不允许为空！</br>\"\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576807843221\");\n\t}else if(hourTime==0){\n\t\t//\"重复模式：每几小时不允许为0！</br>\"\n\t\temessage+=\"重复模式：每几小时不允许为0！</br>\";\n\t}\n//按天重复\n}else if(patrolType==\"PATROL_planType/day\"){\n\t//按天重复类型\n\tvar dayType=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.dayRepeatType\").getValue().value;\n\tvar day=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.day\").getValue();\n\tvar workDay=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.workDay\").getValue();\n\t//按天重复\n\tif(dayType==\"PATROL_dayRepeatType/day\" && day==null){\n\t\t//重复模式：每几天不允许为空！</br>\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576808088024\");\n\t}else if(dayType==\"PATROL_dayRepeatType/day\" && day==0){\n\t\t//\"重复模式：每几天不允许为0！</br>\"\n\t\temessage+=\"重复模式：每几天不允许为0！</br>\";\n\t}\n\t//按星期重复\n\tif(dayType==\"PATROL_dayRepeatType/workDay\" && workDay==null){\n\t\t//重复模式：每几工作日不允许为空！</br>\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576808336708\");\n\t}else if(dayType==\"PATROL_dayRepeatType/workDay\" && workDay==0 ){\n\t\t//\"重复模式：每几工作日不允许为0！</br>\"\n\t\temessage+=\"重复模式：每几工作日不允许为0！</br>\";\n\t}\n\t//按周重复\n}else if(patrolType==\"PATROL_planType/week\"){\n\tvar weekTime=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.weekInterval\").getValue();\n\tvar weekDays=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekDay\").getValue();\n\tif(weekTime==null){\n        //\"重复模式：每几周不允许为空！</br>\"\n        emessage+=ReactAPI.international.getText(\"PATROL.custom.randon1582695863933\");\n\t}else if(weekTime==0){\n\t\t//\"重复模式：每几周的周几不允许为0！</br>\"\n\t\temessage+=\"重复模式：每几周不允许为0！</br>\";\n\t}else if(weekDays==null){\n\t\t//\"重复模式：每几周的周几不允许为空！</br>\"\n\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576817906709\");\n\t}else if(weekDays===0){\n\t\t//\"重复模式：每几周的周几不允许为0！</br>\"\n\t\temessage+=\"重复模式：每几周的周几不允许为0！</br>\";\n\t}\n\t//按月重复\n}else if(patrolType==\"PATROL_planType/month\"){\n\t//按月重复类型\n\tvar monthType=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.monthRepeatType\").getValue().value;\n\t//按天重复\n\tif(monthType==\"PATROL_monthRepeatType/day\"){\n\t\tvar months=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").getValue();//1\n\t\tvar days=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichDay\").getValue();//1\t\t\n\t\tif(months==null) {\n           // \"重复模式：每几月不允许为空！</br>\"\n            emessage+=ReactAPI.international.getText(\"PATROL.custom.randon1582696521366\");\n\t\t}else if(months==0){\n            // \"重复模式：每几月不允许为0！</br>\"\n\t\t\temessage+=\"重复模式：每几月不允许为0!</br>\";\n\t\t}else if(days==null){\n            // \"重复模式：每几月的第几天不允许为空！</br>\"\n\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576818815834\");\n\t\t}else if(days==0){\n            // \"重复模式：每几月的第几天不允许为空！</br>\"\n\t\t\temessage+=\"重复模式：每几月的第几天不允许为空！</br>\";\n\t\t}else{\n\t\t\tif(days>31){\n\t\t\t\t//按月重复：每个月不允许超过31天！\n\t\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1579393594747\");\n\t\t\t}\n\t\t}\t\n\t//按星期重复\n\t}else if(monthType==\"PATROL_monthRepeatType/week\"){\n\t\tvar monthss=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntWeek\").getValue();//2\n\t\tvar dayss=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichWeek\").getValue();//2\n\t\tvar weekDayss=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekMonth\").getValue();\n\t\tif(monthss==null){\n\t\t\t// \"重复模式：每几月不允许为空！</br>\"\n            emessage+=ReactAPI.international.getText(\"PATROL.custom.randon1582696521366\");\n\t\t}else if(monthss==0){\n\t\t\t//\"重复模式：每几月不允许为空！</br>\"\n\t\t\temessage+=\"重复模式：每几月不允许为0！</br>\";        \n\t\t}else if(dayss==null){\n\t\t\t//每几月的第几周不允许为空\n\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1582696562640\");        \n\t\t}else if(dayss==0){\n\t\t\t//每几月的第几周不允许为0\n\t\t\temessage+=\"每几月的第几周不允许为0</br>\";        \n\t\t}else if(weekDayss==null){\n\t\t\t // \"重复模式：每几月的第几周的周几不允许为空！</br>\"\n\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1576818879993\");\n\t\t}else if(weekDayss==0){\n\t\t\t // \"重复模式：每几月的第几周的周几不允许为0！</br>\"\n\t\t\temessage+=\"重复模式：每几月的第几周的周几不允许为0！</br>\";\n\t\t}else {\n\t\t\tif(dayss>5){\n\t\t\t\t//按月重复：每个月不允许超过6周！\n\t\t\t\temessage+=ReactAPI.international.getText(\"PATROL.custom.randon1579394154425\");\n\t\t\t}\n\t\t}\n\t}\n\t\n}\nconsole.log(999999);\n//人员分配\nvar assignType=ReactAPI.getComponentAPI(\"SystemCode\"