og(obj);\n\t//单次\n\tif(obj==\"PATROL_planType/single\"){\n\t\t//隐藏按月重复\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").setValue();\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntWeek\").setValue();\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichDay\").setValue();\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichWeek\").setValue();\n\t\tReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekMonth\").setValue();\n\t\t$(''div[data-key=\"patrolPlan.monthIntDay\"]'').parents(\"tr\").hide();\n\t\t$(''div[data-key=\"patrolPlan.monthIntWeek\"]'').parents(\"tr\").hide();\n\t\t//隐藏按周重复\n\t\tReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekDay\").setValue();\n\t\t$(''div[data-key=\"patrolPlan.weekInterval\"]'').parents(\"tr\").hide();\n\t\t//隐藏按天重复\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.day\").setValue();\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.workDay\").setValue();\n\t\t$(''div[data-key=\"patrolPlan.day\"]'').parents(\"tr\").hide();\n\t\t//按小时重复\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.hour\").setValue();\n\t\t$(''div[data-key=\"patrolPlan.hour\"]'').parents(\"tr\").hide();\n\t\t//结束时间设置\n\t\tReactAPI.getComponentAPI(\"DatePicker\").APIs(\"patrolPlan.endTime\").setValue();\n\t\tReactAPI.getComponentAPI(\"DatePicker\").APIs(\"patrolPlan.endTime\").setReadonly(true);\n\t\t$(''input:radio[name=\"finishTime\"]'').eq(1).trigger(\"click\");\n\t\t$(''[name=\"finishTime\"]'').attr(\"disabled\",\"disabled\");\n\t\t// 选中重复几次模式\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.repeatNum\").setValue(1);\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.repeatNum\").setReadonly(true);\n\t//按小时重复\n\t}else if(obj==\"PATROL_planType/hour\"){\n\t\t//隐藏按月重复\n\t\tReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").setValue();\n\t\tReactAPI.getCom