l.getText(\"PATROL.patrolPlan.PatrolPlan.day\");\n\t\t}\n\t\t//按星期重复\n\t\tif(dayType==\"PATROL_dayRepeatType/workDay\"){\n\t\t\tplanPeriod=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.workDay\").getValue();\n\t\t\tplanPeriodUnit=ReactAPI.international.getText(\"foundation.calendar.workday\");\n\t\t}\n\t\t//按周重复\n\t}else if(patrolType==\"PATROL_planType/week\"){\n\t\tplanPeriod=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.weekInterval\").getValue();\n\t\tplanPeriodUnit=ReactAPI.international.getText(\"ec.scheduler.job.intervalUnit.week\");\n\t\t//按月重复\n\t}else if(patrolType==\"PATROL_planType/month\"){\n\t\t//按月重复类型\n\t\tvar monthType=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.monthRepeatType\").getValue().value;\n\t\tplanPeriodUnit=ReactAPI.international.getText(\"foundation.calendarWeekday.month\");\n\t\t//按天重复\n\t\tif(monthType==\"PATROL_monthRepeatType/day\"){\n\t\t\tplanPeriod=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").getValue();//1\n\t\t//按星期重复\n\t\t}else if(monthType==\"PATROL_monthRepeatType/week\"){\n\t\t\tplanPeriod=ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntWeek\").getValue();//2\n\t\t}\n\t\t\n\t}else{\n\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1577358868777\"));\n\t\treturn false;\n\t}\n\tif(!planPeriod || !planPeriodUnit){\n\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1577086013087\"));\n\t\treturn false;\n\t}\n\tvar exePeriodId;\n\tvar url=\"\";\n\tif(ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362\").getDatagridData().length>0){\n\t\texePeriodId=ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolPlan_patrolPlandg1578568095362\").getDatagridData()[0].id\n\t}\n\t\n\tif(exePeriodId){\n\t\turl=\"/msService/PATROL/patrolPlan/exceptPeriod/exceptionPerodEdit?planType=\"+patrolType+\"&planPeriod=\"+planPeriod+