t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576807843221\");\n\t}\n\t//按天重复\n} else if (patrolType == \"PATROL_planType/day\") {\n\t//按天重复类型\n\tvar dayType = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.dayRepeatType\").getValue().value;\n\tvar day = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.day\").getValue();\n\tvar workDay = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.workDay\").getValue();\n\t//按天重复\n\tif (dayType == \"PATROL_dayRepeatType/day\" && (day == 0 || !day)) {\n\t\t//重复模式：每几天不允许为空！</br>\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576808088024\");\n\t}\n\t//按星期重复\n\tif (dayType == \"PATROL_dayRepeatType/workDay\" && (workDay == 0 || !workDay)) {\n\t\t//重复模式：每几工作日不允许为空！</br>\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576808336708\");\n\t}\n\t//按周重复\n} else if (patrolType == \"PATROL_planType/week\") {\n\tvar weekTime = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.weekInterval\").getValue();\n\tvar weekDays = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekDay\").getValue();\n\tif (!weekTime || weekTime == 0) {\n\t\t//\"重复模式：每几周不允许为空！</br>\"\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1582695863933\");\n\t} else if (!weekDays || weekDays === 0) {\n\t\t//\"重复模式：每几周的周几不允许为空！</br>\"\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576817906709\");\n\t}\n\t//按月重复\n} else if (patrolType == \"PATROL_planType/month\") {\n\t//按月重复类型\n\tvar monthType = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.monthRepeatType\").getValue().value;\n\t//按天重复\n\tif (monthType == \"PATROL_monthRepeatType/day\") {\n\t\tvar months = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").getValue(); //1\n\t\tvar days = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichDay\").getValue(); //1\t\t\n\t\tif (months == 0 || !months) {\n\t\t\t// \"重复模式：每几月不允许为空！</br>\"\n\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1582696521366\");\n\t\t} else if (days == 0 || !days) {\n\t\t\t// \"重复模式：每几月的第几天不允许为空！</br>\"\n\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576818815834\");\n\t\t} else {\n\t\t\tif (days > 31) {\n\t\t\t\t//按月重复：每个月不允许超过31天！\n\t\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1579393594747\");\n\t\t\t}\n\t\t}\n\t\t//按星期重复\n\t} else if (monthType == \"PATROL_monthRepeatType/week\") {\n\t\tvar monthss = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntWeek\").getValue(); //2\n\t\tvar dayss = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.whichWeek\").getValue(); //2\n\t\tvar weekDayss = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.weekMonth\").getValue();\n\t\tif (monthss == 0 || !monthss) {\n\t\t\t// \"重复模式：每几月不允许为空！</br>\"\n\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1582696521366\");\n\t\t} else if (dayss == 0 || !dayss) {\n\t\t\t//每几月的第几周不为空\n\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1582696562640\");\n\t\t} else if (!weekDayss || weekDayss == 0) {\n\t\t\t// \"重复模式：每几月的第几周的周几不允许为空！</br>\"\n\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1576818879993\");\n\t\t} else {\n\t\t\tif (dayss > 5) {\n\t\t\t\t//按月重复：每个月不允许超过6周！\n\t\t\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1579394154425\");\n\t\t\t}\n\t\t}\n\t}\n}\nconsole.log(999999);\n//人员分配\nvar assignType = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"patrolPlan.staffAssignType\").getValue().value;\nif (assignType == \"PATROL_staffAssign/staff\") {\n\tvar roleIds = ReactAPI.getComponentAPI(\"Reference\").APIs(\"patrolPlan.patrolPlanRoleId\").getValue();\n\tvar staffIds = ReactAPI.getComponentAPI(\"Reference\").APIs(\"patrolPlan.patrolPlanStaffId\").getValue();\n\t//人员和角色都为空时\n\tif (roleIds.length == 0 && staffIds.length == 0) {\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1577357663675\");\n\t}\n} else if (assignType == \"PATROL_staffAssign/team\") {\n\tvar teamName = ReactAPI.getComponentAPI(\"Reference\").APIs(\"patrolPlan.team.name\").getValue();\n\tif (!teamName || teamName.length == 0) {\n\t\temessage += ReactAPI.international.getText(\"PATROL.custom.randon1577357776648\");\n\t}\n}\n\nif (emessage) {\n\tReactAPI.showMessage(\"f\", emessage);\n\treturn false;\n}\n//校验例外作业的周期必须为巡检周期的整数倍\nvar exePeriod = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolPlan_patrolPlandg1576648050133\").getValueByKey(0, ''period'');\nif (exePeriod) {\n\tvar num = \"\";\n\t//天\n\tif (\"PATROL_planType/day\" == patrolType) {\n\t\tnum = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.day\").getValue();\n\n\t\t//小时\n\t} else if (\"PATROL_planType/hour\" == patrolType) {\n\t\tnum = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.hour\").getValue();\n\n\t\t//星期\n\t} else if (\"PATROL_planType/week\" == patrolType) {\n\t\tnum = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.weekInterval\").getValue();;\n\n\t\t//月\n\t} else if (\"PATROL_planType/month\" == patrolType) {\n\t\tnum = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").getValue() == \"\" ? ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntWeek\").getValue() : ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.monthIntDay\").getValue();\n\t}\n\tif (exePeriod < num || exePeriod == num || exePeriod % num != 0) {\n\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1577102786139\"));\n\t\treturn false;\n\t}\n}\n\n//巡检提前开始时间\nvar advanceTime = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.advanceStartTime\").getValue();\n//巡检延迟结束时间\nvar delayTime = ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"patrolPlan.delayStartTime\").getValue();\n//巡检提前开始时间和巡检延迟结束时间不允许同时为空\nif (advanceTime && delayTime) {\n\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1579071628809\"));\n\treturn false;\n}","name":"onsave_es5"}]}', 0)
