SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506219664\");\n    //巡检区域表格\n    var areaTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708\");\n    //巡检项表格\n    var itemTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575507309041\");\n    //获取选中行\n    var selectRow = routeTable.getSelecteds();\n    if (selectRow.length == 0) {\n        //至少选择一条记录！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"ec.common.checkselected\"));\n        return false;\n    }\n    //校验非本公司数据\n    if (!checkEditPower(selectRow)) {\n    return false;\n    }\n    //组装参数\n    var routeList = new Array();\n    var routeIds = new Array();\n    selectRow.forEach(function (element, index) {\n        routeList.push({\n            index: index,\n            routeId: element.id\n        });\n        routeIds.push(element.id);\n    });\n    //校验巡检路线是否关联巡检计划\n    var checkStr = \"\";\n    ReactAPI.request(\n        {\n            type: \"post\",\n            url: \"/msService/PATROL/patrolRoute/workGroup/checkRelationPlan\",\n            async: false,\n            data: routeList\n        },\n        function (res) {\n            console.log(res);\n            if (res.code == 200) {\n                //请求成功\n                if (res.data) {\n                    res.data.forEach(function (element) {\n                        var route = selectRow[element.index];\n                        checkStr += \"<b>\" + route.name + \"</b>,\";\n                    });\n                }\n            } else {\n                //发生内部错误，请联系管理员！\n                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"greendill.show.title.500\"));\n            }\n        });\n    if (checkStr != \"\") {\n        //巡检路线[{0}]存在巡检计划，不允许删除！\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1611024814055\", checkStr.substr(0, (checkStr.length - 1))));\n        return false;\n    }\n    //弹出确认框\n    //确认删除吗？\n    ReactAPI.openConfirm({\n        //删除时将会同时删除巡检路线下的巡检区域和巡检项，确认删除吗？\n        message: ReactAPI.international.getText(\"PATROL.custom.randon1578725549579\"),\n        buttons: [\n            {\n                operatetype: \"yes\",\n                text: ReactAPI.international.getText(\"calendar.common.check\"),//确认\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                    //删除巡检路线\n                    //处理中...\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                    ReactAPI.request(\n                        {\n                            type: \"get\",\n                            url: \"/msService/PATROL/patrolRoute/workGroup/deleteWorkGroups?routeIds=\" + routeIds\n                        },\n                        function (res) {\n                            //关闭过度框\n                            ReactAPI.closeLoading();\n                            if (res.code == 200) {\n                                //处理成功\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n                                //刷新表格\n                                routeTable.refreshDataByRequst();\n                                areaTable.refreshDataByRequst();\n                                itemTable.refreshDataByRequst();\n\n                            } else {\n                                //发生内部错误，请联系管理员！\n                                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"greendill.show.title.500\"));\n                            }\n                        }\n                    );\n                }\n            },\n            {\n                operatetype: \"no\",\n                text: ReactAPI.international.getText(\"calendar.common.cancal\"),\n 