lick: function onClick(event) {\n\t\t\t\tReactAPI.destroyDialog(\"workItemRef\");\n\t\t\t}\n\t\t}]\n\t});\n}","id":"workItemRef","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"funcbody":"function insertLineClick(){\n    var itemTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507\");\n    //获取选中的行\n    var selectedData = itemTable.getSelecteds();\n    if(selectedData.length!=1){\n        //请选择一条记录进行操作！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"SupDatagrid.button.error\") );\n        return;\n    }\n    //获取巡检区域的 路线id和设备id\n    var areaTable = parent.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708\");\n\tvar selectRow=areaTable.getSelecteds()[0].rowIndex;\n    var deviceId=areaTable.getValueByKey(selectRow,''device.id'');\n    var devide=areaTable.getValueByKey(selectRow,''device.name'');\n    var workRouteId=areaTable.getValueByKey(selectRow,''workGroupId.id'');\n\n    var insertRowIndex = selectedData[0].rowIndex;\n    itemTable.insertLine(insertRowIndex);\n    itemTable.setRowData(insertRowIndex,{\n        routeId:{\n            id:workRouteId\n        }\n    });\n    if(devide){\n        itemTable.setValueByKey(insertRowIndex,''eamId'',{id:deviceId,name:devide});\n    }\n}","funcname":"onclick=''insertLineClick()''","buttonstyle":"insert","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1605862227474_2046","isHide":false,"showname":"插行","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFJvdXRlX3dvcmtJdGVtUHRFZGl0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"ec.view.button.insertRow","funcbody_es5":"function insertLineClick() {\n    var itemTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507\");\n    //获取选中的行\n    var selectedData = itemTable.getSelecteds();\n    if (selectedData.length != 1) {\n        //请选择一条记录进行操作！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"SupDatagrid.button.error\"));\n        return;\n    }\n    //获取巡检区域的 路线id和设备id\n    var areaTable = parent.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workGroupListdg1575506226708\");\n    var selectRow = areaTable.getSelecteds()[0].rowIndex;\n    var deviceId = areaTable.getValueByKey(selectRow, ''device.id'');\n    var devide = areaTable.getValueByKey(selectRow, ''device.name'');\n    var workRouteId = areaTable.getValueByKey(selectRow, ''workGroupId.id'');\n\n    var insertRowIndex = selectedData[0].rowIndex;\n    itemTable.insertLine(insertRowIndex);\n    itemTable.setRowData(insertRowIndex, {\n        routeId: {\n            id: workRouteId\n        }\n    });\n    if (devide) {\n        itemTable.setValueByKey(insertRowIndex, ''eamId'', { id: deviceId, name: devide });\n    }\n}","id":"insertLine","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"buttonstyle":"own-sy","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1586484667824_9130","isHide":false,"showname":"上移","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFJvdXRlX3dvcmtJdGVtUHRFZGl0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"ec.view.button.moveRowUp","id":"moveUpward","operatetype":"MOVEUP","isconfirm":false},{"isSignatureConfig":true,"buttonstyle":"own-xy","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1586484705840_1054","isHide":false,"showname":"下移","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFJvdXRlX3dvcmtJdGVtUHRFZGl0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"ec.view.button.moveRowDown","id":"moveDown","operatetype":"MOVEDOWN","isconfirm":false}],"autoresize":false,"DataGridCode":"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507","listPT":false,"renderOver_es5":"//巡检项对象\nvar dataObjects = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolRoute_workItemPtEditdg1575632686507\");\n//pt长度\nvar length = dataObjects.getDatagridData().length;\nfor (var i = 0; i < length; i++) {\n\t//编辑方式\n\tvar editType = dataObjects.getDatagridData()[i].inputStandardId.editType.id;\n\t//值类型\n\tvar valueType = dataObjects.getDatagridData()[i].inputStandardId.valType.id;\n\t//自动判定\n\tvar autojude = dataObjects.getDatagridData()[i].isAutoJudge;\n\t//录入可以编辑\n\tif (editType == \"PATROL_editType/input\" && valueType == \"PATROL_valueType/number\") {\n\t\t//正常范围可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''normalRange'', { readonly: false });\n\t\t//默认值可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''defaultVal'', { readonly: false });\n\t\t//自动判定可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''isAutoJudge'', { readonly: false });\n\t\t//上限值和下限值可编辑和清空\n\t\tdataObjects.setDatagridCellAttr(i, ''lowerLimit'', { readonly: false });\n\t\tdataObjects.setDatagridCellAttr(i, ''upperLimit'', { readonly: false });\n\n\t\t//测温、测震可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''isThermometric'', { readonly: false });\n\t\tdataObjects.setDatagridCellAttr(i, ''isSeismic'', { readonly: false });\n\t} else if (editType == \"PATROL_editType/singleSelect\" || editType == \"PATROL_editType/whether\") {\n\t\t//单选 \n\t\t//清空正常范围\n\t\tdataObjects.setDatagridCellAttr(i, ''normalRange'', { readonly: false });\n\t\t//清空默认值\n\t\tdataObjects.setDatagridCellAttr(i, ''defaultVal'', { readonly: false });\n\t\t//自动判定可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''isAutoJudge'', { readonly: false });\n\t\t//上限值和下限值不可编辑和清空\n\t\tdataObjects.setDatagridCellAttr(i, ''lowerLimit'', { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, ''upperLimit'', { readonly: true });\n\n\t\t//测温、测震不可编辑\n\t\t//测温、测震为空\n\t\tdataObjects.setDatagridCellAttr(i, ''isThermometric'', { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, ''isSeismic'', { readonly: true });\n\t\tReactAPI.request({\n\t\t\ttype: \"get\",\n\t\t\turl: \"/msService/PATROL/patrolRoute/workItem/isExeRuleWork?workItemId=\" + dataObjects.getValueByKey(i, ''id''),\n\t\t\tasync: false\n\t\t}, function (msg) {\n\t\t\tif (msg.data.dealFlag == true) {\n\t\t\t\tdataObjects.setDatagridCellAttr(i, ''inputStandardId.code'', { readonly: true });\n\t\t\t}\n\t\t});\n\t} else {\n\t\t//清空正常范围\n\t\tdataObjects.setValueByKey(i, ''normalRange'', '''');\n\t\t//正常范围不可编辑\n\t\tdataObjects.setDatagridCellAttr(i, ''normalRange'', { readonly: true });\n\t\t//自动判定赋值为false\n\t\tdataObjects.setValueByKey(i, ''isAutoJudge'', false);\n\t\tdataObjects.setDatagridCellAttr(i, ''isAutoJudge'', { readonly: true });\n\t\t//上限值和下限值不可编辑和清空\n\t\tdataObjects.setValueByKey(i, ''upperLimit'', '''');\n\t\tdataObjects.setValueByKey(i, ''lowerLimit'', '''');\n\t\tdataObjects.setDatagridCellAttr(i, ''lowerLimit'', { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, ''upperLimit'', { readonly: true });\n\t\t//测温、测震不可编辑\n\t\t//测温、测震为空\n\t\tdataObjects.setDatagridCellAttr(i, ''isThermometric'', { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, ''isSeismic'', { readonly: true });\n\t\tdataObjects.setValueByKey(i, ''isSeismic'', false);\n\t\tdataObjects.setValueByKey(i, ''isThermometric'', false);\n\t\t//默认值不可编辑\n\t\tdataObjects.setValueByKey(i, ''defaultVal'', '''');\n\t\tdataObjects.setDatagridCellAttr(i, ''defaultVal'', { readonly: true });\n\t}\n\t//如果自动判定为否，则正常范围不可编辑\n\tif (!autojude) {\n\t\tdataObjects.setDatagridCellAttr(i, ''normalRange'', { readonly: true });\n\t}\n\n\t//值类型为 数字 编辑方式为 录入的 采集误差对标才设置 可编辑\n\tif (valueType == ''PATROL_valueType/number'' && editType == ''PATROL_editType/input'') {\n\t\tdataObjects.setDatagridCellAttr(i, \"isErrorBench\", { readonly: false });\n\t\tdataObjects.setDatagridCellAttr(i, \"errorBenchUpper\", { readonly: false });\n\t} else {\n\t\tdataObjects.setDatagridCellAttr(i, \"isErrorBench\", { readonly: true });\n\t\tdataObjects.setDatagridCellAttr(i, \"errorBenchUpper\", { readonly: true });\n\t}\n}","copyRow":false,"queryUrl":null,"sav