t\t\t//自动判定赋值为true\n\t\t\tgridObj.setValueByKey(row, ''isAutoJudge'', true);\n\t\t\t//上限值和下限值不可编辑和清空\n\t\t\tgridObj.setValueByKey(row, ''upperLimit'', '''');\n\t\t\tgridObj.setValueByKey(row, ''lowerLimit'', '''');\n\t\t\tgridObj.setDatagridCellAttr(row, ''lowerLimit'', { readonly: true });\n\t\t\tgridObj.setDatagridCellAttr(row, ''upperLimit'', { readonly: true });\n\n\t\t\t//测温、测震不可编辑\n\t\t\t//测温、测震为空\n\t\t\tgridObj.setDatagridCellAttr(row, ''isThermometric'', { readonly: true });\n\t\t\tgridObj.setDatagridCellAttr(row, ''isSeismic'', { readonly: true });\n\t\t\tgridObj.setValueByKey(row, ''isSeismic'', false);\n\t\t\tgridObj.setValueByKey(row, ''isThermometric'', false);\n\t\t} else if (editType == \"PATROL_editType/input\" && valueType == \"PATROL_valueType/number\") {\n\t\t\t//录入且数值\n\t\t\t//清空正常范围\n\t\t\tgridObj.setValueByKey(row, ''normalRange'', '''');\n\t\t\t//正常范围可编辑\n\t\t\tgridObj.setDatagridCellAttr(row, ''normalRange'', { readonly: false });\n\t\t\t//清空默认值\n\t\t\tgridObj.setValueByKey(row, ''defaultVal'', '''');\n\t\t\t//默认值可编辑\n\t\t\tgridObj.setDatagridCellAttr(row, ''defaultVal'', { readonly: false });\n\t\t\t//自动判定赋值为true\n\t\t\tgridObj.setValueByKey(row, ''isAutoJudge'', true);\n\t\t\t//自动判定可编辑\n\t\t\tgridObj.setDatagridCellAttr(row, ''isAutoJudge'', { readonly: false });\n\t\t\t//上限值和下限值可编辑和清空\n\t\t\tgridObj.setValueByKey(row, ''upperLimit'', '''');\n\t\t\tgridObj.setValueByKey(row, ''lowerLimit'', '''');\n\t\t\tgridObj.setDatagridCellAttr(row, ''lowerLimit'', { readonly: false });\n\t\t\tgridObj.setDatagridCellAttr(row, ''upperLimit'', { readonly: false });\n\n\t\t\t//测温、测震可编辑\n\t\t\tgridObj.setDatagridCellAttr(row, ''isThermometric'', { readonly: false });\n\t\t\tgridObj.setDatagridCellAttr(row, ''isSeismic'', { readonly: false });\n\t\t} else {\n\t\t\t//清空正常范围\n\t\t\tgridObj.setValueByKey(row, ''normalRange'', '''');\n\t\t\t//正常范围不可编辑\n\t\t\tgridObj.setDatagridCellAttr(row, ''normalRange'', { readonly: true });\n\t\t\t//自动判定赋值为false\n\t\t\tgridO