ence","mneType":"Staff","url":"/organization/#/reference?type=staff","openType":"dialog","height":null},"crosscol":false,"ecEnv":"product","propertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_patrolTask||PATROL_1.0.0_patrolTask_PotrolTask_modifyStaff||base_staff_name","readonly":false,"layRec":"MP_POTROL_TASKS,ID,MP_TASK_DETAILS,PATROL_TASK-base_staff,ID,MP_POTROL_TASKS,MODIFY_STAFF_ID-name","modelCode":"sysbase_1.0_staff_base_staff","namekey":"PATROL.formPropertyshowName.randon1584672753090.flag","showType":"SELECTCOMP","exp":"like","key":"patrolTask.modifyStaff.name","entityCode":"PATROL_1.0.0_patrolTask","showFormat":"SELECTCOMP","moduleCode":"PATROL_1.0.0","iscrosscompany":false,"caseSensitive":false,"mnecode":true,"selfType":"TEXT","fullPropertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_patrolTask||PATROL_1.0.0_patrolTask_PotrolTask_modifyStaff||base_staff_name","columnType":"TEXT","isrefselect":false,"name":"patrolTask.modifyStaff.name","modelcode":"sysbase_1.0_staff_base_staff","multable":false,"maxLength":80,"columnName":"NAME"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"buttons":[{"isSignatureConfig":true,"funcbody":"function createTask() {\n    //获取所选择的数据\n    var dataSelect = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg\").getSelecteds();\n   //校验非本公司数据\n   if (!checkEditPower(dataSelect)) {\n\treturn false;\n    }\n\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg\");\n    //获取选中的数据\n    var selectData = table.getSelecteds();\n    if (selectData.length == 0) {\n        //请至少选中一行！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"Reference.confirm.tip.message\"));\n        return false;\n    }\n    var ids = \"\";\n    for (var i = 0; i < selectData.length; i++) {\n        var dataItem = selectData[i];\n        var rowIndex = dataItem.rowIndex + 1;\n        if (dataItem.isFault == true) {\n            //第{0}行，巡检任务已生成隐患单，不能再次生成！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"PATROL.custom.danger.created\", rowIndex));\n            return false;\n        }\n        ids += dataItem.id + \",\";\n    }\n    // 默认按钮\n    ReactAPI.openConfirm({\n        //\"是否生成隐患单？\"\n        message: ReactAPI.international.getText(\"PATROL.custom.danger.isCreated\"),\n        onOk: function () {\n            ReactAPI.closeConfirm();\n            //生成隐患单\n            var url = ''/msService/PATROL/patrolTask/taskDetail/createHiddenDanger'';\n            var params = {\n                ids: ids\n            };\n            //异步\n            _postAsyncWithLoading(url, params, function (res) {\n                if (res.code == 200) {\n                    ReactAPI.showMessage(\"s\", res.message);\n                    //点击查询按钮\n                    $(\"button[data-id=''query'']\").click();\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            }, function (res) {\n                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n            }, ReactAPI.international.getText(\"PATROL.custom.danger.creating\"));\n        }\n    });\n}","funcname":"onclick=''createTask()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1584681582288_6908","buttonoperationcode":"abnormalSummary_createTask_add_PATROL_1.0.0_patrolTask_abnormalSummary","isHide":false,"showname":"生成隐患单","ecEnv":"product","pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFRhc2tfYWJub3JtYWxTdW1tYXJ5X3NlbGZ8","regionType":"BUTTON","iscallback":false,"modelCode":"PATROL_1.0.0_patrolTask_TaskDetail","namekey":"PATROL.buttonPropertyshowName.randon1584681731415.flag","funcbody_es5":"function createTask() {\n    //获取所选择的数据\n    var dataSelect = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg\").getSelecteds();\n    //校验非本公司数据\n    if (!checkEditPower(dataSelect)) {\n        return false;\n    }\n\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_abnormalSummary_taskDetail_sdg\");\n    //获取选中的数据\n    var selectData = table.getSelecteds();\n    if (selectData.length == 0) {\n        //请至少选中一行！\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"Reference.confirm.tip.message\"));\n        return false;\n    }\n    var ids = \"\";\n    for (var i = 0; i < selectData.length; i++) {\n        var dataItem = selectData[i];\n        var rowIndex = dataItem.rowIndex + 1;\n        if (dataItem.isFault == true) {\n            //第{0}行，巡检任务已生成隐患单，不能再次生成！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"PATROL.custom.danger.created\", rowIndex));\n            return false;\n        }\n        ids += dataItem.id + \",\";\n    }\n    // 默认按钮\n    ReactAPI.openConfirm({\n        //\"是否生成隐患单？\"\n        message: ReactAPI.international.getText(\"PATROL.custom.danger.isCreated\"),\n        onOk: function onOk() {\n            ReactAPI.closeConfirm();\n            //生成隐患单\n            var url = ''/msService/PATROL/patrolTask/taskDetail/createHiddenDanger'';\n            var params = {\n                ids: ids\n            };\n            //异步\n            _postAsyncWithLoading(url, params, function (res) {\n                if (res.code == 200) {\n                    ReactAPI.showMessage(\"s\", res.message);\n                    //点击查询按钮\n                    $(\"button[data-id=''query'']\").click();\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            }, function (res) {\n                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n            }, ReactAPI.international.getText(\"PATROL.custom.danger.creating\"));\n        }\n    });\n}","id":"createTask","operatetype":"CUSTOM