patrolTask_batchChangeList\";\n        ReactAPI.getPowerCode(operateCode, function(res) {\n            powerCode = res[operateCode];\n            var url=\"/msService/PATROL/patrolTask/potrolTask/patrolStateEdit?__pc__=\" + powerCode +\"&id=\"+taskId+\"&idList=\"+idList;\n            ReactAPI.createDialog(\"newDialog\", {\n                title:ReactAPI.international.getText(\"PATROL.viewtitle.randon1578017423020\") ,\n                size:1 ,\n                url: url,\n                isRef: false, // 是否开启参照\n                buttons: [\n                {\n                  text: ReactAPI.international.getText(\"calendar.common.save\"),\n                  type: \"primary\",\n                  style: { color: \"#fff\", background: \"#58c9cb\" },\n                  onClick: function(event) {\n                    console.log(11111111);\n                    debugger;\n                    var changeState =event.ReactAPI.getComponentAPI(''SystemCode'').APIs(''potrolTask.taskState'').getValue().value;\n                    var remark = event.ReactAPI.getComponentAPI(''TextArea'').APIs(\"potrolTask.remark\").getValue();\n                    var idList=ReactAPI.getParamsInRequestUrl(event.window.location.href).idList;\n                    if(!changeState){\n                        event.ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"potrolTask.taskState\").setValidateStyle(''error'',ReactAPI.international.getText(\"PATROL.custom.randon1578030877786\"));\n                        return false;\n                    }else{\n                        event.ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"potrolTask.taskState\").setValidateStyle(''success'');\n                    }\n                    ReactAPI.request({\n                        type: \"get\",\n                        url: \"/msService/PATROL/patrolTask/potrolTask/taskStateUpdate?changeState=\"+changeState+\"&remark=\"+remark+\"&idList=\"+idList\n                    },function(res) {\n                        event.ReactAPI.openLoading(ReactAPI.international.getText(\"ec.common.saving\"));\n                        setTimeout(function(){\n                            event.ReactAPI.closeLoading();\n                            ReactAPI.destroyDialog(\"newDialog\");\n                        }, 600);\n                        \n                        \n                        ReactAPI.getComponentAPI(\"SearchPanel\").APIs(\"PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sp\").updateSearch()\n                        //ReactAPI.destroyDialog(\"refDialog\");\n                    });\n                  }\n                },\n                {\n                  text: ReactAPI.international.getText(\"ec.common.cancel\"),\n                  onClick: event => {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                  }\n                }\n              ]\n            });\n        });\n    }","funcname":"onclick=''taskStateChange()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":true,"cellCode":"cell_1578028190671_7388","buttonoperationcode":"batchChangeList_taskStateChange_add_PATROL_1.0.0_patrolTask_batchChangeList","isHide":false,"showname":"状态变更","ecEnv":"product","pc":"__pc__=YmF0Y2hDaGFuZ2VMaXN0X3Rhc2tTdGF0ZUNoYW5nZV9hZGRfUEFUUk9MXzEuMC4wX3BhdHJvbFRhc2tfYmF0Y2hDaGFuZ2VMaXN0fA__","regionType":"BUTTON","iscallback":false,"modelCode":"PATROL_1.0.0_patrolTask_PotrolTask","namekey":"PATROL.buttonPropertyshowName.randon1578028171895.flag","funcbody_es5":"function taskStateChange() {\n    //获取所选择的数据\n    var dataSelect = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sdg\").getSelecteds();\n    //校验非本公司数据\n    if (!checkEditPower(dataSelect)) {\n        return false;\n    }\n    var taskSelectRow = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sdg\").getSelecteds();\n    //判断是否选中数据\n    if (taskSelectRow.length == 0) {\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"foundation.common.selectNullData\"));\n        return false;\n    }\n    /*for(var i=0;i<taskSelectRow.length;i++){\n        var taskState=taskSelectRow[i].taskState.id;\n        if(\"PATROL_taskState/notIssued\"!=taskState){\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"PATROL.custom.randon1578984268384\")); \n            return  false;\n        }\n    }*/\n    //处理id数据变成数组数据传递\n    var idList = new Array();\n    var taskId = taskSelectRow[0].id;\n    $(taskSelectRow).each(function (index, element) {\n        idList.push(element.id);\n    });\n    var powerCode = \"\";\n    var operateCode = \"batchChangeList_taskStateChange_add_PATROL_1.0.0_patrolTask_batchChangeList\";\n    ReactAPI.getPowerCode(operateCode, function (res) {\n        powerCode = res[operateCode];\n        var url = \"/msService/PATROL/patrolTask/potrolTask/patrolStateEdit?__pc__=\" + powerCode + \"&id=\" + taskId + \"&idList=\" + idList;\n        ReactAPI.createDialog(\"newDialog\", {\n            title: ReactAPI.international.getText(\"PATROL.viewtitle.randon1578017423020\"),\n            size: 1,\n            url: url,\n            isRef: false, // 是否开启参照\n            buttons: [{\n                text: ReactAPI.international.getText(\"calendar.common.save\"),\n                type: \"primary\",\n                style: { color: \"#fff\", background: \"#58c9cb\" },\n                onClick: function onClick(event) {\n                    console.log(11111111);\n                    debugger;\n                    var changeState = event.ReactAPI.getComponentAPI(''SystemCode'').APIs(''potrolTask.taskState'').getValue().value;\n                    var remark = event.ReactAPI.getComponentAPI(''TextArea'').APIs(\"potrolTask.remark\").getValue();\n                    var idList = ReactAPI.getParamsInRequestUrl(event.window.location.href).idList;\n                    if (!changeState) {\n               