ist.push(element.id);\n    });\n    var powerCode = \"\";\n    var operateCode = \"batchChangeList_assignStaff_add_PATROL_1.0.0_patrolTask_batchChangeList\";\n    ReactAPI.getPowerCode(operateCode, function (res) {\n        powerCode = res[operateCode];\n        var url = \"/msService/PATROL/patrolTask/potrolTask/staffChangeEdit?__pc__=\" + powerCode + \"&id=\" + taskId + \"&idList=\" + idList;\n        ReactAPI.createDialog(\"newDialog\", {\n            title: ReactAPI.international.getText(\"PATROL.viewtitle.randon1578017423020\"),\n            size: 1,\n            url: url,\n            isRef: false, // 是否开启参照\n            buttons: [{\n                text: ReactAPI.international.getText(\"calendar.common.save\"),\n                type: \"primary\",\n                style: { color: \"#fff\", background: \"#58c9cb\" },\n                onClick: function onClick(event) {\n                    console.log(11111111);\n                    var staffIds = event.ReactAPI.getComponentAPI(\"Reference\").APIs(\"potrolTask.patrolTaskStaffId\").getValue();\n                    if (staffIds.length == 0) {\n                        event.ReactAPI.getComponentAPI(\"Reference\").APIs(\"potrolTask.patrolTaskStaffId\").setValidateStyle(''error'', ReactAPI.international.getText(\"PATROL.custom.randon1578194334198\"));\n                        return false;\n                    } else {\n                        event.ReactAPI.getComponentAPI(\"Reference\").APIs(\"potrolTask.patrolTaskStaffId\").setValidateStyle(''success'');\n                    }\n                    var staffList = new Array();\n                    $(staffIds).each(function (index, element) {\n                        staffList.push(element.id);\n                    });\n                    var idList = ReactAPI.getParamsInRequestUrl(event.window.location.href).idList;\n                    ReactAPI.request({\n                        type: \"get\",\n                        url: \"/msService/PATROL/patrolTask/potrolTask/staffBatchChange?staffList=\" + staffList + \"&idList=\" + idList\n                    }, function (res) {\n                        event.ReactAPI.openLoading(ReactAPI.international.getText(\"ec.common.saving\"));\n                        setTimeout(function () {\n                            event.ReactAPI.closeLoading();\n                            ReactAPI.destroyDialog(\"newDialog\");\n                        }, 600);\n\n                        ReactAPI.getComponentAPI(\"SearchPanel\").APIs(\"PATROL_1.0.0_patrolTask_batchChangeList_potrolTask_sp\").updateSearch();\n                        //ReactAPI.destroyDialog(\"refDialog\");\n                    });\n                }\n            }, {\n                text: ReactAPI.international.getText(\"ec.common.cancel\"),\n                onClick: function onClick(event) {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                }\n            }]\n        });\n    });\n}","id":"assignStaff","operatetype":"CUSTOM","isconfirm":false,"CODE":"batchChangeList_assignStaff_add_PATROL_1.0.0_patrolTask_batchChangeList","NAME":"指派负责人","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"}],"importMainXls":"/msService/PATROL/patrolTask/potrolTask/importMainXls","mainDisplayName":"id","isTransCondition":false,"renderOver_es5":"ReactAPI.getComponentAPI(''SystemCode'').APIs(''taskState'').removeOption(''PATROL_taskState/completed'');\nReactAPI.getComponentAPI(''SystemCode'').APIs(''taskState'').removeOption(''PATROL_taskState/cancelled'');\nReactAPI.getComponentAPI(''SystemCode'').APIs(''taskState'').removeOption(''PATROL_taskState/overdue'');","nodeExpanded":false,"layoutmethod":"container","isExportExcel":true,"hasFastQuery":true,"isTreeView":false,"fields":[{"precisionHasChanged":false,"code":"PATROL_1.0.0_patrolTask_batchChangeList_LISTPT_OTHER_PATROL_1.0.0_patrolTask_PotrolTask_tableNo","isTotal":false,"isOrderBy":false,"seniorSystemcode":false,"displayName":"ec.common.tableNo","showFormatHasChanged"