 = 0; i < tableData.length; i++) {\n\tvar itemData = tableData[i];\n\tvar rowIndex = itemData.rowIndex;\n\t//巡检项是否拍照\n\tvar isPhoto = itemData.workItemId.isPhone;\n\t//实际是否拍照\n\tvar isRealPhoto = itemData.isRealPhoto;\n\tif (isPhoto) {\n\t\t//将实际拍照设置为勾选\n\t\teditTable.setValueByKey(rowIndex, \"isRealPhoto\", true);\n\t\tisRealPhoto = true;\n\t}\n\t//是否允许跳过\n\tvar isPass = itemData.isPass;\n\tif (isPass == null || isPass == false) {\n\t\t//实际跳过不可编辑\n\t\teditTable.setDatagridCellAttr(rowIndex, \"isRealPass\", { readonly: true });\n\t}\n\t//实际是否跳过\n\tvar isRealPass = itemData.isRealPass;\n\tif (isRealPass == null || isRealPass == false) {\n\t\t//未跳过，跳过原因不可编辑，只读\n\t\teditTable.setDatagridCellAttr(rowIndex, \"passReason.value\", { readonly: true });\n\t}\n\n\tif (isRealPhoto == null || isRealPhoto == false) {\n\t\t//未拍照，附件不可编辑，只读\n\t\teditTable.setDatagridCellAttr(rowIndex, \"attachmentMultiFileNames\", { readonly: true });\n\t}\n\t//如果默认值，则填入实际结果中\n\tvar defaultValue = itemData.defaultValue;\n\teditTable.setValueByKey(rowIndex, \"concluse\", $.trim(defaultValue));\n\n\t//获取是否自动判断\n\tvar isAutoJudge = itemData.autoJudge;\n\tif (isAutoJudge != null && isAutoJudge == true) {\n\t\t//执行自动判定\n\t\tvar value = $.trim(defaultValue);\n\t\tif (value != null && value !== \"\") {\n\t\t\t//获取正常范围\n\t\t\tvar normalRange = itemData.normalRange;\n\t\t\t//获取值类型\n\t\t\tvar valType = itemData.inputStandardId.valType;\n\t\t\t//获取编辑方式\n\t\t\tvar editType = itemData.inputStandardId.editType;\n\t\t\tvar isNormal = judge(valType, editType, value, normalRange);\n\t\t\tvar realValueid = \"\";\n\t\t\tvar realValue = \"\";\n\t\t\tif (isNormal == true) {\n\t\t\t\trealValueid = \"PATROL_realValue/normal\"; //正常\n\t\t\t\trealValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600907721\");\n\t\t\t} else if (isNormal == false) {\n\t\t\t\trealValueid = \"PATROL_realValue/abnormal\"; //异常\n\t\t\t\trealValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon158460091595