hange(value,rowNum)''","code":"PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503_DATAGRID_OTHER_PATROL_1.0.0_patrolTask_TaskDetail_concluse","nullable":true,"isTotal":false,"displayName":"PATROL.patrolTask.TaskDetail.concluse","showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_concluse","regionType":"DATAGRID","layRec":"concluse","modelCode":"PATROL_1.0.0_patrolTask_TaskDetail","namekey":"PATROL.patrolTask.TaskDetail.concluse","isreadonly":false,"showType":"TEXTFIELD","isgroup":false,"key":"concluse","popView":false,"funcbody":"function change(value, rowNum) {\n    //获取表格对象\n    var editTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503\");\n    //获取值类型\n    var valType = editTable.getValueByKey(rowNum, \"inputStandardId.valType\");\n    //获取编辑方式\n    var editType = editTable.getValueByKey(rowNum, \"inputStandardId.editType\");\n    //数字 录入 类型的有小数位,所以根据小数位对值进行处理\n    if (valType.id === \"PATROL_valueType/number\" && editType.id === \"PATROL_editType/input\") {\n        if(isNaN(value)){\n            value = \"\";\n            //修改页面显示\n            setTimeout(function(){\n                editTable.setValueByKey(rowNum, \"concluse\", value)\n            });\n        }\n        //获取小数位\n        var decimalPlace = editTable.getValueByKey(rowNum, \"workItemId.inputStandardId.decimalPlace\");\n        //如果 小数位不为空 \n        if (decimalPlace || decimalPlace === 0) {\n            if (decimalPlace < 0) {\n                decimalPlace = 0;\n            }\n            if(value){\n                value = Number(value).toFixed(decimalPlace);\n                //修改页面显示\n                setTimeout(function(){\n                    editTable.setValueByKey(rowNum, \"concluse\", value)\n                });\n            }\n        }\n    }\n\n    //获取是否自动判断\n    var isAutoJudge = editTable.getValueByKey(rowNum, \"autoJudge\");\n    if (isAutoJudge && isAutoJudge == true) {\n        //获取正常范围\n        var normalRange = editTable.getValueByKey(rowNum, \"normalRange\");\n        if (value == null || value === \"\") {\n            editTable.setValueByKey(rowNum, \"realValue\", null);\n            editTable.setValueByKey(rowNum, \"realValue.value\", null);\n            return;\n        }\n        value = $.trim(value);\n        editTable.setValueByKey(rowNum, \"concluse\", value);\n        var isNormal = judge(valType, editType, value, normalRange);\n        var realValueid = \"\";\n        var realValue = \"\";\n        if(isNormal == true){\n            realValueid = \"PATROL_realValue/normal\";//正常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600907721\");\n        }else if (isNormal == false){\n            realValueid = \"PATROL_realValue/abnormal\";//异常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600915950\");\n        }\n        //下拉选择框时 一个realValue为向后台传入的值（页面显示不会改变），realValue.value 为页面展示的值（不会传入后台），所以都要设置\n        editTable.setValueByKey(rowNum, \"realValue\", { id: realValueid });\n        editTable.setValueByKey(rowNum, \"realValue.value\", realValue);\n    }\n}","showFormat":"TEXT","entityCode":"PATROL_1.0.0_patrolTask","moduleCode":"PATROL_1.0.0","cellCode":"cell_1584600683983_3116","mneenable":false,"label":"实际结果","fullPropertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_concluse","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFRhc2tfZW50ZXJpbmdSZXN1bHRFZGl0X3NlbGZ8","width":100,"textalign":"left","isCustom":false,"funcbody_es5":"function change(value, rowNum) {\n    //获取表格对象\n    var editTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503\");\n    //获取值类型\n    var valType = editTable.getValueByKey(rowNum, \"inputStandardId.valType\");\n    //获取编辑方式\n    var editType = editTable.getValueByKey(rowNum, \"inputStandardId.editType\");\n    //数字 录入 类型的有小数位,所以根据小数位对值进行处理\n    if (valType.id === \"PATROL_valueType/number\" && editType.id === \"PATROL_editType/input\") {\n        if (isNaN(value)) {\n            value = \"\";\n            //修改页面显示\n            setTimeout(function () {\n                editTable.setValueByKey(rowNum, \"concluse\", value);\n            });\n        }\n        //获取小数位\n        var decimalPlace = editTable.getValueByKey(rowNum, \"workItemId.inputStandardId.decimalPlace\");\n        //如果 小数位不为空 \n        if (decimalPlace || decimalPlace === 0) {\n            if (decimalPlace < 0) {\n                decimalPlace = 0;\n            }\n            if (value) {\n                value = Number(value).toFixed(decimalPlace);\n                //修改页面显示\n                setTimeout(function () {\n                    editTable.setValueByKey(rowNum, \"concluse\", value);\n                });\n            }\n        }\n    }\n\n    //获取是否自动判断\n    var isAutoJudge = editTable.getValueByKey(rowNum, \"autoJudge\");\n    if (isAutoJudge && isAutoJudge == true) {\n        //获取正常范围\n        var normalRange = editTable.getValueByKey(rowNum, \"normalRange\");\n        if (value == null || value === \"\") {\n            editTable.setValueByKey(rowNum, \"realValue\", null);\n            editTable.setValueByKey(rowNum, \"realValue.value\", null);\n            return;\n        }\n        value = $.trim(value);\n        editTable.setValueByKey(rowNum, \"concluse\", value);\n        var isNormal = judge(valType, editType, value, normalRange);\n        var realValueid = \"\";\n        var realValue = \"\";\n        if (isNormal == true) {\n            realValueid = \"PATROL_realValue/normal\"; //正常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600907721\");\n        } else if (isNormal == false) {\n            realValueid = \"PATROL_realValue/abnormal\"; //异常\n            realValue = ReactAPI.international.getText(\"PATROL.systemCodevalue.randon1584600915950\");\n        }\n        //下拉选择框时 一个realValue为向后台传入的值（页面显示不会改变），realValue.value 为页面展示的值（不会传入后台），所以都要设置\n        editTable.setValueByKey(rowNum, \"realValue\", { id: realValueid });\n        editTable.setValueByKey(rowNum, \"realValue.value\", realValue);\n    }\n}","multable":false,"maxLength":200,"columnName":"CONCLUSE"},{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503_DATAGRID_OTHER_PATROL_1.0.0_patrolTask_TaskDetail_realValue","nullable":true,"isTotal":false,"displayName":"PATROL.patrolTask.TaskDetail.realValue","showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"SYSTEMCODE","propertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_realValue","regionType":"DATAGRID","layRec":"realValue","modelCode":"PATROL_1.0.0_patrolTask_TaskDetail","namekey":"PATROL.patrolTask.TaskDetail.realValue","isreadonly":false,"showType":"SELECTCOMP","isgroup":false,"key":"realValue","popView":false,"showFormat":"SELECTCOMP","entityCode":"PATROL_1.0.0_patrolTask","moduleCode":"PATROL_1.0.0","cellCode":"cell_1584601031078_6570","mneenable":false,"label":"实际结论","fullPropertyCode":"PATROL_1.0.0_patrolTask_TaskDetail_realValue","fill":{"fillType":3,"fillName":"系统编码","fillContent":"PATROL_realValue","listType":"list"},"isHidden":false,"columnType":"SYSTEMCODE","hide":false,"isrefselect":false,"pc":"__pc__=UEFUUk9MXzEuMC4wX3BhdHJvbFRhc2tfZW50ZXJpbmdSZXN1bHRFZGl0X3NlbGZ8","width":100,"textalign":"center","isCustom":false,"multable":false,"maxLength":4000,"columnName":"REAL_VALUE"},{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"funcname":"onchange=''change(value,rowNum)''","code":"PATROL_1.0.0_patrolTask_enteringResultEditdg1584600022503_DATAGRID_OTHER_PATROL_1.0.0_patrolTask_TaskDetail_isRealPass","nullable":true,"isTotal":false,"displayName":"PATROL.patrolTask.TaskDetail.isRealPass"